// SafeCollector.emit, on every call:
// 1. ensureActive() on the emitting coroutine        -> CancellationException
// 2. same context as collect (Job may differ by scope) -> IllegalStateException "Flow invariant is violated"
// 3. no emit after a failed emit                       -> IllegalStateException "Flow exception transparency is violated"

val plates = flow {
    for (dish in dinner) emit(dish)                  // no try around emit
}
plates.collect { dish ->
    try {
        diner.eat(dish)
    } catch (e: SentBackException) {
        println("SORRY $dish came back: ${e.message}")  // catch where the failure happens
    }
}

